# generate output for manually transcribed test; calculate potential bridges and print concise changed coords, dimensions and grid
h,w=26,29
marks=[(0,2),(4,3),(4,5),(5,16),(6,18),(7,15),(8,5),(9,16),(10,25),(11,0),(11,16),(12,6),(13,12),(14,20),(14,24),(16,6),(17,14),(17,17),(18,13),(19,14),(19,27),(20,21),(22,22),(22,28),(25,8)]
g=[[2]*w for _ in range(h)]
for r,c in marks:g[r][c]=6
paint=set()
for r in range(h):
 cs=sorted(c for rr,c in marks if rr==r)
 for a,b in zip(cs,cs[1:]):paint.update((r,c) for c in range(a+1,b))
for c in range(w):
 rs=sorted(r for r,cc in marks if cc==c)
 for a,b in zip(rs,rs[1:]):paint.update((r,c) for r in range(a+1,b))
for r,c in paint:g[r][c]=3
print('dims',len(g),set(map(len,g)),'changed',len(paint),'rows')
for r,row in enumerate(g): print(r, ' '.join(map(str,row)))
